        raise JournalError(no, "account line needs an account path")
    path = _word(tokens, 1, no, "an account path")
    if not valid_path(path):
        raise JournalError(no, "invalid account path '%s'" % path)
    i = 2
    cur = None
    opened = closed = None
    note = ""
    if i < len(tokens) and tokens[i][0] == _WORD and tokens[i][1] not in ("open", "close"):
        cur = tokens[i][1]
        if cur not in CURRENCIES:
            raise JournalError(no, "unknown currency '%s'" % cur)
        i += 1
    if i < len(tokens) and tokens[i] == (_WORD, "open"):
        opened = _date(_word(tokens, i + 1, no, "a date after 'open'"), no)
        i += 2
    if i < len(tokens) and tokens[i] == (_WORD, "close"):
        closed = _date(_word(tokens, i + 1, no, "a date after 'close'"), no)
        i += 2
    if i < len(tokens) and tokens[i][0] == _QUOTED:
        note = tokens[i][1]
        i += 1
    if i < len(tokens):
        raise JournalError(no, "unexpected '%s' in account line" % tokens[i][1])
    if opened is not None and closed is not None and closed < opened:
        raise JournalError(no, "account %s closes before it opens" % path)
    if path in seen:
        raise JournalError(no, "account %s is declared twice" % path)
    seen.add(path)
    return Account(path, account_type(path), cur, opened, closed, note)


def _parse_rate(tokens, comment, no):
    if len(tokens) != 5 or any(k != _WORD for k, _ in tokens):
        raise JournalError(no, "rate line must be: rate DATE FROM TO RATE")
    on = _date(tokens[1][1], no)
    src, dst, text = tokens[2][1], tokens[3][1], tokens[4][1]
    for c in (src, dst):
        if c not in CURRENCIES:
            raise JournalError(no, "unknown currency '%s'" % c)
    if src == dst:
        raise JournalError(no, "rate needs two different currencies, got %s twice" % src)
    if not _RATE_RE.fullmatch(text):
        raise JournalError(no, "invalid rate '%s'" % text)
    if Fraction(text) <= 0:
        raise JournalError(no, "invalid rate '%s': must be positive" % text)
    return (src, dst, on, text)


def _parse_tx_line(tokens, comment, no):
    on = _date(tokens[0][1], no) if tokens[0][0] == _WORD else None
    if on is None:
        raise JournalError(no, "expected a date at the start of the line")
    i = 1
    flag = "*"
    if i < len(tokens) and tokens[i][0] == _WORD and tokens[i][1] in ("*", "!"):
        flag = tokens[i][1]
        i += 1
    if i >= len(tokens) or tokens[i][0] != _QUOTED:
        raise JournalError(no, "expected a quoted payee")
    payee = tokens[i][1]
    i += 1
    narration = ""
    if i < len(tokens) and tokens[i][0] == _QUOTED:
        narration = tokens[i][1]
        i += 1
    tags = set()
    while i < len(tokens):
        kind, text = tokens[i]
        if kind != _WORD:
            raise JournalError(no, "unexpected quoted text in transaction line")
        if not _TAG_RE.fullmatch(text):
            raise JournalError(no, "unexpected '%s' in transaction line" % text)
        tags.add(text[1:])
        i += 1
    return Transaction(on, payee, narration, [], tuple(sorted(tags)), flag, None)


def _parse_posting(tokens, comment, no):
    if any(k != _WORD for k, _ in tokens):
        raise JournalError(no, "unexpected quoted text in posting")
    if not tokens:
        raise JournalError(no, "posting needs an account")
    account = tokens[0][1]
    if not valid_path(account):
        raise JournalError(no, "invalid account path '%s'" % account)
    amount = None
    if len(tokens) == 3:
        try:
            amount = Money.of(tokens[1][1], tokens[2][1])
        except TallybookError as e:
            raise JournalError(no, e.message) from None
    elif len(tokens) == 2:
        raise JournalError(no, "amount '%s' needs a currency" % tokens[1][1])
    elif len(tokens) > 3:
        raise JournalError(no, "unexpected '%s' in posting" % tokens[3][1])
    note = comment.strip(_BLANK) if comment is not None else ""
    return Posting(account, amount, note)


def parse_journal(text):
    if not isinstance(text, str):
        raise JournalError(1, "journal must be text")
    if text.startswith("﻿"):
        text = text[1:]
    lines = text.replace("\r\n", "\n").split("\n")
    journal = Journal()
    seen = set()
    current = None
    for no, line in enumerate(lines, 1):
        stripped = line.strip(_BLANK)
        if not stripped:
            current = None
            continue
        if stripped[0] in ";#":
            continue
        tokens, comment = _tokenize(line, no)
        if line[0] in _BLANK:
            if current is None:
                raise JournalError(no, "indented line outside a transaction")
            current.postings.append(_parse_posting(tokens, comment, no))
            continue
        current = None
        head = tokens[0] if tokens else None
        if head == (_WORD, "account"):
            journal.accounts.append(_parse_account(tokens, comment, no, seen))
        elif head == (_WORD, "rate"):
            journal.rates.append(_parse_rate(tokens, comment, no))
        else:
            current = _parse_tx_line(tokens, comment, no)
            journal.transactions.append(current)
    return journal


# -- writing ------------------------------------------------------------


def _quote(text):
    return '"' + str(text).replace("\\", "\\\\").replace('"', '\\"') + '"'


def _account_line(a):
    out = "account " + a.path
    if a.currency:
        out += " " + a.currency
    if a.opened is not None:
        out += " open " + format_date(a.opened)
    if a.closed is not None:
        out += " close " + format_date(a.closed)
    if a.note:
        out += " " + _quote(a.note)
    return out + "\n"


def _rate_line(rate):
    src, dst, on, text = rate
    return "rate %s %s %s %s\n" % (format_date(on), src, dst, text)


def format_transaction(tx):
    head = "%s %s %s" % (format_date(tx.date), tx.flag, _quote(tx.payee))
    if tx.narration:
        head += " " + _quote(tx.narration)
    for tag in sorted(set(tx.tags)):
        head += " #" + tag
    lines = [head]
    with_amount = [p for p in tx.postings if p.amount is not None]
    acct_w = max((len(p.account) for p in with_amount), default=0)
    amt_w = max((len(p.amount.amount_str()) for p in with_amount), default=0)
    for p in tx.postings:
        if p.amount is not None:
            line = "  %s  %s %s" % (
                p.account.ljust(acct_w),
                p.amount.amount_str().rjust(amt_w),
                p.amount.currency,
            )
        else:
            line = "  " + p.account
        note = p.note.strip(_BLANK) if p.note else ""
        if note:
            line += "  ; " + note
        lines.append(line)
    return "\n".join(lines) + "\n"


def format_journal(journal):
    blocks = []
    if journal.accounts:
        blocks.append("".join(_account_line(a) for a in journal.accounts))
    if journal.rates:
        blocks.append("".join(_rate_line(r) for r in journal.rates))
    for tx in journal.transactions:
        blocks.append(format_transaction(tx))
    return "\n".join(blocks)

"""The query language: finding transactions."""
import operator
import re
from fractions import Fraction

from .dates import DateError, Period, parse_date
from .errors import ParseError


class QueryError(ParseError):
    def __init__(self, description, position=1):
        self.position = position
        self.description = description
        super().__init__("%s at position %d" % (description, position))

    def __reduce__(self):
        return (QueryError, (self.description, self.position))


_WS = " \t\r\n\f\v"
_STOP = _WS + "()"
_KEYWORDS = ("and", "or", "not")
_TEXT_NAMES = ("payee", "narration", "tag", "date", "flag", "id", "account")
_CMP_NAMES = ("amount", "date")
_KNOWN_NAMES = _TEXT_NAMES + ("amount",)
_OPS = {
    "<=": operator.le,
    ">=": operator.ge,
    "!=": operator.ne,
    "<": operator.lt,
    ">": operator.gt,
    "=": operator.eq,
}
_NAME_RE = re.compile(r"[A-Za-z]+")
_PART_RE = re.compile(r"[A-Za-z0-9_-]+")
_ID_RE = re.compile(r"[0-9]+")
_AMOUNT_RE = re.compile(r"([+-]?[0-9]+(?:\.[0-9]+)?)([A-Z]{3})?")
_MAX_DEPTH = 100

# token kinds
_EOF, _LP, _RP, _KW, _TERM = "eof", "(", ")", "kw", "term"


def _pattern_parts(pattern):
    parts = pattern.split(":")
    for p in parts:
        if p not in ("*", "**") and not _PART_RE.fullmatch(p):
            return None
    return parts


def _account_matches(parts, account):
    if not isinstance(account, str):
        return False
    segs = account.split(":")
    n = len(segs)
    reach = {0}
    for part in parts:
        nxt = set()
        for i in reach:
            if part == "**":
                nxt.update(range(i, n + 1))
            elif i < n and (part == "*" or part == segs[i]):
                nxt.add(i + 1)
        if not nxt:
            return False
        reach = nxt
    return True


class _Parser:
    def __init__(self, text, chart):
        self.text = text
        self.chart = chart
        self.n = len(text)
        self.pos = 0
        self.depth = 0
        self.tok = None
        self._advance()

    # -- lexer -------------------------------------------------------------
    def _err(self, description, index):
        raise QueryError(description, index + 1)

    def _skip_ws(self, i):
        while i < self.n and self.text[i] in _WS:
            i += 1
        return i

    def _word_end(self, i):
        while i < self.n and self.text[i] not in _STOP:
            i += 1
        return i

    def _advance(self):
        i = self._skip_ws(self.pos)
        text = self.text
        if i >= self.n:
            self.pos = i
            self.tok = (_EOF, None, self.n)
            return
        c = text[i]
        if c == "(" or c == ")":
            self.pos = i + 1
            self.tok = (c, None, i)
            return
        if c != '"':
            end = self._word_end(i)
            if text[i:end].lower() in _KEYWORDS:
                self.pos = end
                self.tok = (_KW, text[i:end].lower(), i)
                return
        node, end = self._term(i)
        self.pos = end
        self.tok = (_TERM, node, i)

    def _quoted(self, i):
        """Read a quoted string opening at i; return (value, index after the closing quote)."""
        text, n = self.text, self.n
        j = i + 1
        buf = []
        while j < n:
            ch = text[j]
            if ch == "\\" and j + 1 < n and text[j + 1] in ('"', "\\"):
                buf.append(text[j + 1])
                j += 2
                continue
            if ch == '"':
                j += 1
                if j < n and text[j] not in _STOP:
                    self._err("unexpected text after a closing quote", j)
                return "".join(buf), j
            buf.append(ch)
            j += 1
        self._err("unterminated quote", i)

    def _value(self, start, i):
        """Read the value starting at i (after 'name:'); return (value, end)."""
        if i < self.n and self.text[i] == '"':
            value, end = self._quoted(i)
            if value == "":
                self._err("empty quotes", start)
            return value, end
        end = self._word_end(i)
        if end == i:
            self._err("missing value", start)
        return self.text[i:end], end

    def _term(self, i):
        text = self.text
        if text[i] == '"':
            value, end = self._quoted(i)
            if value == "":
                self._err("empty quotes", i)
            return _plain(value), end
        e = self._word_end(i)
        word = text[i:e]
        colon = word.find(":")
        if colon >= 0:
            name = word[:colon].lower()
            if name not in _TEXT_NAMES:
                if name == "amount":
                    self._err("amount needs a comparison operator, not ':'", i)
                self._err("unknown term name '%s'" % word[:colon], i)
            value, end = self._value(i, i + colon + 1)
            return self._named(name, value, i), end
        m = _NAME_RE.match(word)
        if m and m.group().lower() in _KNOWN_NAMES:
            name = m.group().lower()
            p = self._skip_ws(i + m.end())
            op = None
            for cand in ("<=", ">=", "!=", "<", ">", "="):
                if text.startswith(cand, p):
                    op = cand
                    break
            if op is not None:
                if name not in _CMP_NAMES:
                    self._err("'%s' takes ':' and not a comparison operator" % name, i)
                q = self._skip_ws(p + len(op))
                end = self._word_end(q)
                if end == q:
                    self._err("missing value", i)
                return self._compare(name, op, text[q:end], i), end
        return _plain(word), e

    def _compare(self, name, op, value, start):
        fn = _OPS[op]
        if name == "date":
            try:
                want = parse_date(value)
            except DateError:
                self._err("invalid date '%s'" % value, start)
            return lambda tx, p: fn(tx.date, want)
        m = _AMOUNT_RE.fullmatch(value)
        if not m:
            self._err("invalid amount '%s'" % value, start)
        want = Fraction(m.group(1))
        cur = m.group(2)

        def amount_term(tx, p):
            amt = p.amount
            if amt is None:
                return False
            if cur is not None and amt.currency != cur:
                return False
            return fn(Fraction(amt.minor, 10 ** amt.exponent), want)

        return amount_term

    def _named(self, name, value, start):
        if name == "payee":
            low = value.lower()
            return lambda tx, p: low in tx.payee.lower()
        if name == "narration":
            low = value.lower()
            return lambda tx, p: low in tx.narration.lower()
        if name == "tag":
            low = value.lower()
            return lambda tx, p: any(t.lower() == low for t in tx.tags)
        if name == "date":
            try:
                period = Period.parse(value)
            except DateError:
                self._err("invalid period '%s'" % value, start)
            return lambda tx, p: period.start <= tx.date <= period.end
        if name == "flag":
            if value not in ("*", "!"):
                self._err("invalid flag '%s' (expected * or !)" % value, start)
            return lambda tx, p: tx.flag == value
        if name == "id":
            if not _ID_RE.fullmatch(value):
                self._err("invalid id '%s'" % value, start)
            want = int(value)
            return lambda tx, p: (
                isinstance(tx.id, int) and not isinstance(tx.id, bool) and tx.id == want
            )
        parts = _pattern_parts(value)
        if parts is None:
            self._err("invalid account pattern '%s'" % value, start)
        if self.chart is not None:
            if not any(_account_matches(parts, a.path) for a in self.chart.accounts()):
                self._err("no account matches '%s'" % value, start)
        return lambda tx, p: _account_matches(parts, p.account)

    # -- parser ------------------------------------------------------------
    def parse(self):
        if self.tok[0] == _EOF:
            return None
        node = self._or()
        if self.tok[0] == _RP:
            self._err("unmatched ')'", self.tok[2])
        return node

    def _need_term(self):
        kind, _, at = self.tok
        if kind in (_RP, _EOF) or (kind == _KW and self.tok[1] != "not"):
            what = "end of the query" if kind == _EOF else "'%s'" % (")" if kind == _RP else self.tok[1])
            self._err("expected a term but found %s" % what, at)

    def _or(self):
        kids = [self._and()]
        while self.tok[0] == _KW and self.tok[1] == "or":
            self._advance()
            kids.append(self._and())
        return kids[0] if len(kids) == 1 else _any(kids)

    def _and(self):
        kids = [self._not()]
        while True:
            kind, val, _ = self.tok
            if kind in (_EOF, _RP) or (kind == _KW and val == "or"):
                break
            if kind == _KW and val == "and":
                self._advance()
            kids.append(self._not())
        return kids[0] if len(kids) == 1 else _all(kids)

    def _not(self):
        nots = 0
        while self.tok[0] == _KW and self.tok[1] == "not":
            nots += 1
            self._advance()
        node = self._primary()
        if nots % 2:
            inner = node
            return lambda tx, p: not inner(tx, p)
        return node

    def _check_depth(self):
        self.depth += 1
        if self.depth > _MAX_DEPTH:
            self._err("query is nested too deeply", self.tok[2])

    def _primary(self):
        self._need_term()
        kind, val, at = self.tok
        if kind == _LP:
            self._check_depth()
            self._advance()
            node = self._or()
            if self.tok[0] != _RP:
                self._err("'(' is never closed", at)
            self._advance()
            self.depth -= 1
            return node
        self._advance()
        return val


def _plain(word):
    low = word.lower()
    return lambda tx, p: low in tx.payee.lower() or low in tx.narration.lower()


def _any(kids):
    return lambda tx, p: any(k(tx, p) for k in kids)


def _all(kids):
    return lambda tx, p: all(k(tx, p) for k in kids)


class Query:
    def __init__(self, text, node):
        self.text = text
        self._node = node

    @property
    def is_empty(self):
        return self._node is None

    def __repr__(self):
        return "Query(%r)" % (self.text,)

    def matching_postings(self, tx):
        if self._node is None:
            return list(tx.postings)
        node = self._node
        return [p for p in tx.postings if node(tx, p)]

    def matches(self, tx):
        if self._node is None:
            return True
        node = self._node
        return any(node(tx, p) for p in tx.postings)


def parse_query(text, chart=None):
    if not isinstance(text, str):
        raise QueryError("query must be text", 1)
    try:
        node = _Parser(text, chart).parse()
    except RecursionError:
        raise QueryError("query is nested too deeply", 1) from None
    return Query(text, node)


def select(transactions, query):
    if isinstance(query, str):
        query = parse_query(query)
    elif not isinstance(query, Query):
        raise QueryError("query must be a Query or text", 1)
    return [tx for tx in transactions if query.matches(tx)]

