"""Rules: a small hand-written file that sorts transactions into accounts."""
import dataclasses
import re
from fractions import Fraction

from .dates import DateError, is_date, parse_date
from .errors import ParseError
from .model import Posting
from .money import Money

_WS = " \t"
_STOP = " \t<>=!~\""
_FIELDS = ("payee", "narration", "amount", "date")
_TEXT_FIELDS = ("payee", "narration")
_OPERATORS = ("!~", "!=", "<=", ">=", "<", ">", "=", "~")
_ALLOWED_OPS = {
    "payee": ("=", "!=", "~", "!~"),
    "narration": ("=", "!=", "~", "!~"),
    "amount": ("<", "<=", ">", ">=", "=", "!="),
    "date": ("<", "<=", ">", ">=", "=", "!="),
}
_ACTIONS = ("account", "tag", "narration", "payee", "flag")

_ACCOUNT_RE = re.compile(r"[A-Z][A-Za-z0-9_-]*(?::[A-Z][A-Za-z0-9_-]*)*")
_TAG_RE = re.compile(r"[A-Za-z0-9_-]+")
_AMOUNT_RE = re.compile(r"([+-]?[0-9]+(?:\.[0-9]+)?)([A-Z]{3})?")
_DATE_SHAPE_RE = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2}")


class RulesError(ParseError):
    def __init__(self, message, line=None, detail=None):
        super().__init__(message, detail)
        self.line = line


class _Bad(Exception):
    pass


def valid_account_path(text):
    return isinstance(text, str) and _ACCOUNT_RE.fullmatch(text) is not None


def valid_tag(text):
    return isinstance(text, str) and _TAG_RE.fullmatch(text) is not None


class _Scanner:
    def __init__(self, text):
        self.s = text
        self.i = 0

    def skip_ws(self):
        while self.i < len(self.s) and self.s[self.i] in _WS:
            self.i += 1

    def at_end(self):
        return self.i >= len(self.s)

    def word(self):
        start = self.i
        while self.i < len(self.s) and self.s[self.i] not in _STOP:
            self.i += 1
        return self.s[start:self.i]

    def raw(self):
        start = self.i
        while self.i < len(self.s) and self.s[self.i] not in _WS:
            self.i += 1
        return self.s[start:self.i]

    def operator(self):
        for op in _OPERATORS:
            if self.s.startswith(op, self.i):
                self.i += len(op)
                return op
        return None

    def string(self):
        s = self.s
        if self.i >= len(s) or s[self.i] != '"':
            raise _Bad("text must be written in double quotes")
        self.i += 1
        out = []
        while self.i < len(s):
            c = s[self.i]
            if c == '"':
                self.i += 1
                self.need_boundary()
                return "".join(out)
            if c == "\\":
                if self.i + 1 >= len(s):
                    break
                nxt = s[self.i + 1]
                out.append('"' if nxt == '"' else "\\" + nxt)
                self.i += 2
                continue
            out.append(c)
            self.i += 1
        raise _Bad("string is never closed")

    def need_boundary(self):
        if self.i < len(self.s) and self.s[self.i] not in _WS:
            raise _Bad("unexpected text after value: '%s'" % self.s[self.i:])


def _compare(op, left, right):
    if op == "<":
        return left < right
    if op == "<=":
        return left <= right
    if op == ">":
        return left > right
    if op == ">=":
        return left >= right
    if op == "=":
        return left == right
    return left != right


class _Condition:
    __slots__ = ("field", "op", "value", "currency", "regex")

    def __init__(self, field, op, value, currency=None, regex=None):
        self.field = field
        self.op = op
        self.value = value
        self.currency = currency
        self.regex = regex

    def holds(self, fields):
        field = self.field
        if field in _TEXT_FIELDS:
            got = fields.get(field)
            if got is None:
                got = ""
            if not isinstance(got, str):
                got = str(got)
            if self.op == "=":
                return got.lower() == self.value.lower()
            if self.op == "!=":
                return got.lower() != self.value.lower()
            found = self.regex.search(got) is not None
            return found if self.op == "~" else not found
        if field == "amount":
            got = fields.get("amount")
            if not isinstance(got, Money):
                return False
            if self.currency is not None and got.currency != self.currency:
                return False
            return _compare(self.op, Fraction(got.minor, 10 ** got.exponent), self.value)
        got = fields.get("date")
        if not is_date(got):
            return False
        return _compare(self.op, got, self.value)


class Rule:
    def __init__(self, line, conditions, account=None, tags=(), narration=None, payee=None, flag=None):
        self.line = line
        self.conditions = tuple(conditions)  # empty: matches everything
        self.account = account
        self.tags = tuple(tags)
        self.narration = narration
        self.payee = payee
        self.flag = flag

    def __repr__(self):
        return "Rule(line=%d)" % self.line

    def match(self, fields):
        return all(c.holds(fields) for c in self.conditions)

    def apply(self, fields=None):
        out = {}
        if self.account is not None:
            out["account"] = self.account
        if self.tags:
            out["tags"] = list(self.tags)
        if self.narration is not None:
            out["narration"] = self.narration
        if self.payee is not None:
            out["payee"] = self.payee
        if self.flag is not None:
            out["flag"] = self.flag
        return out

    def categorize(self, tx):
        return _categorize(tx, self.apply())


def _tx_fields(tx):
    first = tx.postings[0].amount if tx.postings else None
    return {"payee": tx.payee, "narration": tx.narration, "date": tx.date, "amount": first}


def _categorize(tx, changes):
    updates = {}
    for key in ("payee", "narration", "flag"):
        if key in changes:
            updates[key] = changes[key]
    updates["tags"] = tuple(sorted(set(tx.tags) | set(changes.get("tags", ()))))
    postings = list(tx.postings)
    if "account" in changes and len(postings) == 2:
        postings[1] = dataclasses.replace(postings[1], account=changes["account"])
    updates["postings"] = postings
    return dataclasses.replace(tx, **updates)


class RuleSet:
    def __init__(self, rules=()):
        self._rules = tuple(rules)

    def __len__(self):
        return len(self._rules)

    def __iter__(self):
        return iter(self._rules)

    def __getitem__(self, index):
        return self._rules[index]

    def __repr__(self):
        return "RuleSet(%d rules)" % len(self._rules)

    def match(self, fields):
        for rule in self._rules:
            if rule.match(fields):
                return rule
        return None

    def apply(self, fields):
        rule = self.match(fields)
        if rule is None:
            return None
        return rule.apply(fields)

    def categorize(self, tx):
        rule = self.match(_tx_fields(tx))
        if rule is None:
            return tx
        return _categorize(tx, rule.apply())


def _parse_condition(sc):
    sc.skip_ws()
    field = sc.word()
    if field == "":
        raise _Bad("condition is missing a field name")
    if field == "any":
        raise _Bad("'any' cannot be combined with other conditions")
    if field == "then":
        raise _Bad("missing condition before 'then'")
    if field not in _FIELDS:
        raise _Bad("unknown field '%s'" % field)
    sc.skip_ws()
    op = sc.operator()
    if op is None:
        raise _Bad("condition on '%s' is missing its operator" % field)
    if op not in _ALLOWED_OPS[field]:
        raise _Bad("operator '%s' does not belong to '%s'" % (op, field))
    sc.skip_ws()
    if sc.at_end():
        raise _Bad("condition on '%s' is missing its value" % field)
    if field in _TEXT_FIELDS:
        value = sc.string()
        if op in ("~", "!~"):
            try:
                regex = re.compile(value, re.IGNORECASE)
            except (re.error, OverflowError, RecursionError, ValueError) as exc:
                raise _Bad("invalid regular expression '%s': %s" % (value, exc))
            return _Condition(field, op, value, regex=regex)
        return _Condition(field, op, value)
    token = sc.raw()
    if field == "amount":
        m = _AMOUNT_RE.fullmatch(token)
        if not m:
            raise _Bad("invalid amount '%s'" % token)
        return _Condition(field, op, Fraction(m.group(1)), currency=m.group(2))
    if not _DATE_SHAPE_RE.fullmatch(token):
        raise _Bad("invalid date '%s': expected YYYY-MM-DD" % token)
    try:
        value = parse_date(token)
    except DateError:
        raise _Bad("invalid date '%s': no such day" % token)
    return _Condition(field, op, value)


def _parse_line(sc, lineno):
    sc.skip_ws()
    if sc.word() != "when" or (not sc.at_end() and sc.s[sc.i] not in _WS):
        raise _Bad("a rule must start with 'when'")
    sc.skip_ws()
    if sc.at_end():
        raise _Bad("rule has no conditions")
    conditions = []
    save = sc.i
    if sc.word() == "any":
        sc.skip_ws()
        if sc.at_end():
            raise _Bad("rule is missing 'then'")
        if sc.word() != "then":
            raise _Bad("'any' cannot be combined with other conditions")
    else:
        sc.i = save
        while True:
            conditions.append(_parse_condition(sc))
            sc.skip_ws()
            if sc.at_end():
                raise _Bad("rule is missing 'then'")
            kw = sc.word()
            if kw == "and":
                sc.skip_ws()
                if sc.at_end():
                    raise _Bad("'and' is missing a condition")
                nxt = sc.i
                peek = sc.word()
                sc.i = nxt
                if peek == "any":
                    raise _Bad("'any' cannot be combined with other conditions")
                continue
            if kw == "then":
                break
            raise _Bad("unexpected '%s' where 'and' or 'then' belongs" % (kw or sc.s[sc.i:]))
    if not sc.at_end() and sc.s[sc.i] not in _WS:
        raise _Bad("unexpected text after 'then'")
    account = narration = payee = flag = None
    tags = []
    count = 0
    while True:
        sc.skip_ws()
        if sc.at_end():
            break
        name = sc.raw()
        if name not in _ACTIONS:
            raise _Bad("unknown action '%s'" % name)
        sc.skip_ws()
        if sc.at_end():
            raise _Bad("action '%s' is missing its value" % name)
        if name in ("narration", "payee"):
            value = sc.string()
        else:
            value = sc.raw()
        count += 1
        if name == "tag":
            if not valid_tag(value):
                raise _Bad("invalid tag name '%s'" % value)
            if value.lower() not in tags:
                tags.append(value.lower())
            continue
        already = {"account": account, "narration": narration, "payee": payee, "flag": flag}[name]
        if already is not None:
            raise _Bad("'%s' given twice" % name)
        if name == "account":
            if not valid_account_path(value):
                raise _Bad("invalid account path '%s'" % value)
            account = value
        elif name == "flag":
            if value not in ("*", "!"):
                raise _Bad("invalid flag '%s': expected * or !" % value)
            flag = value
        elif name == "payee":
            if value.strip() == "":
                raise _Bad("payee may not be empty")
            payee = value
        else:
            narration = value
    if count == 0:
        raise _Bad("rule has nothing after 'then'")
    return Rule(lineno, conditions, account, tags, narration, payee, flag)


def parse_rules(text):
    if not isinstance(text, str):
        raise RulesError("rules must be given as text, got '%s'" % (text,))
    if text.startswith("﻿"):
        text = text[1:]
    rules = []
    for number, raw in enumerate(text.split("\n"), 1):
        if raw.endswith("\r"):
            raw = raw[:-1]
        line = raw.strip(_WS)
        if line == "" or line.startswith("#"):
            continue
        try:
            rules.append(_parse_line(_Scanner(line), number))
        except _Bad as exc:
            raise RulesError("line %d: %s" % (number, exc), number) from None
    return RuleSet(rules)

