"""CSV bank-statement import driven by a small profile file."""
import re
from collections import Counter
from dataclasses import dataclass, field
from datetime import date
from typing import List, Optional, Tuple

from .currency import CURRENCIES
from .errors import ParseError
from .model import Posting, Transaction
from .money import Money, MoneyError, parse_amount
from .rules import RuleSet, parse_rules, valid_account_path, valid_tag


class CsvImportError(ParseError):
    def __init__(self, message, line=None, detail=None):
        super().__init__(message, detail)
        self.line = line


@dataclass(frozen=True)
class ImportProfile:
    date_column: str
    payee_column: str
    currency: str
    account: str
    narration_column: Optional[str] = None
    amount_column: Optional[str] = None
    debit_column: Optional[str] = None
    credit_column: Optional[str] = None
    default_account: Optional[str] = None
    date_format: str = "%Y-%m-%d"
    delimiter: str = ","
    skip_rows: int = 0
    has_header: bool = True
    negate: bool = False
    decimal_separator: str = "."
    thousands_separator: str = ""
    flag: str = "*"
    tags: Tuple[str, ...] = ()


@dataclass
class ImportResult:
    transactions: List[Transaction] = field(default_factory=list)
    duplicates: List[Transaction] = field(default_factory=list)
    errors: List[Tuple[int, str]] = field(default_factory=list)


_DELIMITERS = {"comma": ",", "tab": "\t", "semicolon": ";", "pipe": "|", "space": " "}
_THOUSANDS = {"none": "", "comma": ",", "dot": ".", "space": " ", "apostrophe": "'"}
_THOUSANDS_CHARS = (",", ".", "'", " ")
_BOOLS = {"yes": True, "true": True, "no": False, "false": False}
_COLUMN_SETTINGS = (
    "date_column", "payee_column", "narration_column", "amount_column", "debit_column", "credit_column",
)
_SETTINGS = _COLUMN_SETTINGS + (
    "currency", "account", "default_account", "date_format", "delimiter", "skip_rows", "has_header",
    "negate", "decimal_separator", "thousands_separator", "flag", "tags",
)
_MONTHS = ("jan", "feb", "mar", "apr", "may", "jun", "jul", "aug", "sep", "oct", "nov", "dec")
_MONTH_NAMES = (
    "january", "february", "march", "april", "may", "june", "july", "august", "september",
    "october", "november", "december",
)
_DIRECTIVES = {
    "Y": "year", "y": "year", "m": "month", "b": "month", "B": "month", "d": "day",
}


class _Bad(Exception):
    pass


def _compile_date_format(fmt):
    """Return (compiled regex, [(group name, directive)]); raise _Bad when the format is wrong."""
    if not isinstance(fmt, str):
        raise _Bad("invalid date_format '%s': expected text" % (fmt,))
    parts = []
    seen = {}
    order = []
    i = 0
    while i < len(fmt):
        c = fmt[i]
        if c != "%":
            parts.append(re.escape(c))
            i += 1
            continue
        if i + 1 >= len(fmt):
            raise _Bad("invalid date_format '%s': '%%' at the end" % fmt)
        d = fmt[i + 1]
        i += 2
        if d == "%":
            parts.append("%")
            continue
        if d not in _DIRECTIVES:
            raise _Bad("invalid date_format '%s': unknown directive '%%%s'" % (fmt, d))
        kind = _DIRECTIVES[d]
        if kind in seen:
            raise _Bad("invalid date_format '%s': the %s appears twice" % (fmt, kind))
        seen[kind] = d
        name = "g_" + kind
        order.append((name, d))
        if d == "Y":
            parts.append("(?P<%s>[0-9]{4})" % name)
        elif d == "y":
            parts.append("(?P<%s>[0-9]{2})" % name)
        elif d in ("m", "d"):
            parts.append("(?P<%s>[0-9]{1,2})" % name)
        elif d == "b":
            parts.append("(?P<%s>%s)" % (name, "|".join(_MONTHS)))
        else:
            parts.append("(?P<%s>%s)" % (name, "|".join(_MONTH_NAMES)))
    for kind in ("year", "month", "day"):
        if kind not in seen:
            raise _Bad("invalid date_format '%s': no %s" % (fmt, kind))
    return re.compile("".join(parts), re.IGNORECASE | re.ASCII), order


def _parse_cell_date(cell, matcher):
    rx, order = matcher
    m = rx.fullmatch(cell)
    if not m:
        raise _Bad("invalid date '%s': does not match the date format" % cell)
    year = month = day = None
    for name, d in order:
        text = m.group(name)
        if d == "Y":
            year = int(text)
        elif d == "y":
            year = 2000 + int(text)
        elif d in ("m",):
            month = int(text)
        elif d == "d":
            day = int(text)
        elif d == "b":
            month = _MONTHS.index(text.lower()) + 1
        else:
            month = _MONTH_NAMES.index(text.lower()) + 1
    try:
        return date(year, month, day)
    except ValueError:
        raise _Bad("invalid date '%s': no such day" % cell) from None


def _column_value(value):
    if value.strip(" ") == "":
        raise _Bad("column name is empty")
    if value.startswith("#"):
        digits = value[1:]
        if not re.fullmatch(r"[0-9]+", digits) or int(digits) < 1:
            raise _Bad("invalid column '%s': expected #N with N from 1" % value)
    return value


def _bool_value(name, value):
    got = _BOOLS.get(value.lower())
    if got is None:
        raise _Bad("invalid %s '%s': expected yes/no or true/false" % (name, value))
    return got


def _delimiter_value(value):
    if value in _DELIMITERS:
        return _DELIMITERS[value]
    if len(value) == 1 and value not in ('"', "\n", "\r"):
        return value
    raise _Bad("invalid delimiter '%s'" % value)


def _thousands_value(value):
    if value in _THOUSANDS:
        return _THOUSANDS[value]
    if value in _THOUSANDS_CHARS:
        return value
    raise _Bad("invalid thousands_separator '%s'" % value)


def _tags_value(value):
    names = [part.strip(" ") for part in value.split(",")]
    for name in names:
        if not valid_tag(name):
            raise _Bad("invalid tag name '%s'" % name)
    return tuple(sorted({name.lower() for name in names}))


def _convert(name, value):
    if name in _COLUMN_SETTINGS:
        return _column_value(value)
    if name == "currency":
        if value not in CURRENCIES:
            raise _Bad("unknown currency '%s'" % value)
        return value
    if name in ("account", "default_account"):
        if not valid_account_path(value):
            raise _Bad("invalid account path '%s'" % value)
        return value
    if name == "date_format":
        _compile_date_format(value)
        return value
    if name == "delimiter":
        return _delimiter_value(value)
    if name == "skip_rows":
        if not re.fullmatch(r"[0-9]+", value):
            raise _Bad("invalid skip_rows '%s': expected a whole number" % value)
        return int(value)
    if name in ("has_header", "negate"):
        return _bool_value(name, value)
    if name == "decimal_separator":
        if value not in (".", ","):
            raise _Bad("invalid decimal_separator '%s': expected . or ," % value)
        return value
    if name == "thousands_separator":
        return _thousands_value(value)
    if name == "flag":
        if value not in ("*", "!"):
            raise _Bad("invalid flag '%s': expected * or !" % value)
        return value
    return _tags_value(value)


def parse_profile(text):
    if not isinstance(text, str):
        raise CsvImportError("profile must be given as text, got '%s'" % (text,))
    if text.startswith("﻿"):
        text = text[1:]
    values = {}
    lines = {}
    for number, raw in enumerate(text.split("\n"), 1):
        if raw.endswith("\r"):
            raw = raw[:-1]
        line = raw.strip(" ")
        if line == "" or line.startswith("#"):
            continue
        name, eq, value = line.partition("=")
        if not eq:
            raise CsvImportError("line %d: expected 'setting = value', got '%s'" % (number, line), number)
        name = name.strip(" ")
        value = value.strip(" ")
        if len(value) >= 2 and value.startswith('"') and value.endswith('"'):
            value = value[1:-1]
        if name not in _SETTINGS:
            raise CsvImportError("line %d: unknown setting '%s'" % (number, name), number)
        if name in values:
            raise CsvImportError(
                "line %d: setting '%s' given twice (first on line %d)" % (number, name, lines[name]), number
            )
        try:
            values[name] = _convert(name, value)
        except _Bad as exc:
            raise CsvImportError("line %d: %s" % (number, exc), number) from None
        lines[name] = number
    if values.get("has_header", True) is False:
        for name in _COLUMN_SETTINGS:
            if name in values and not values[name].startswith("#"):
                raise CsvImportError(
                    "line %d: column name '%s' needs a header; use #N when has_header = no"
                    % (lines[name], values[name]),
                    lines[name],
                )
    for name in ("date_column", "payee_column", "currency", "account"):
        if name not in values:
            raise CsvImportError("missing required setting '%s'" % name)
    has_amount = "amount_column" in values
    has_debit = "debit_column" in values
    has_credit = "credit_column" in values
    if has_amount and (has_debit or has_credit):
        raise CsvImportError("amount_column cannot be combined with debit_column or credit_column")
    if has_debit != has_credit:
        raise CsvImportError("debit_column and credit_column must be given together")
    if not has_amount and not has_debit:
        raise CsvImportError("one of amount_column or debit_column with credit_column is required")
    decimal = values.get("decimal_separator", ".")
    thousands = values.get("thousands_separator", "")
    if thousands == decimal:
        raise CsvImportError("decimal_separator and thousands_separator are both '%s'" % decimal)
    return ImportProfile(**values)


def _coerce_profile(profile):
    if isinstance(profile, str):
        return parse_profile(profile)
    if isinstance(profile, ImportProfile):
        return profile
    raise CsvImportError("profile must be an ImportProfile or profile text, got '%s'" % (profile,))


def _coerce_rules(rules):
    if rules is None:
        return None
    if isinstance(rules, str):
        return parse_rules(rules)
    if isinstance(rules, RuleSet):
        return rules
    raise CsvImportError("rules must be a RuleSet, rules text or None, got '%s'" % (rules,))


_LINE_RE = re.compile(r"[^\r\n]*(?:\r\n|\r|\n)?")


def _skip_lines(text, count):
    pos = 0
    n = len(text)
    skipped = 0
    while skipped < count and pos < n:
        pos = _LINE_RE.match(text, pos).end()
        skipped += 1
    return pos


def _records(text, pos, delim, first_line):
    """Yield (line the record starts on, [cells]) for the CSV in text[pos:]."""
    n = len(text)
    line = first_line
    plain = re.compile("[^%s\r\n]*" % re.escape(delim))
    quoted_chunk = re.compile('[^"\r\n]*')
    i = pos
    while i < n:
        start_line = line
        cells = []
        while True:
            buf = []
            if i < n and text[i] == '"':
                i += 1
                while i < n:
                    m = quoted_chunk.match(text, i)
                    buf.append(m.group())
                    i = m.end()
                    if i >= n:
                        break
                    c = text[i]
                    if c == '"':
                        if i + 1 < n and text[i + 1] == '"':
                            buf.append('"')
                            i += 2
                            continue
                        i += 1
                        break
                    if c == "\r" and i + 1 < n and text[i + 1] == "\n":
                        buf.append("\r\n")
                        i += 2
                    else:
                        buf.append(c)
                        i += 1
                    line += 1
            m = plain.match(text, i)
            buf.append(m.group())
            i = m.end()
            cells.append("".join(buf))
            if i < n and text[i] == delim:
                i += 1
                continue
            if i < n:
                if text[i] == "\r" and i + 1 < n and text[i + 1] == "\n":
                    i += 2
                else:
                    i += 1
                line += 1
            break
        yield start_line, cells


def _clean(text):
    return " ".join(text.split())


class _Amounts:
    def __init__(self, profile):
        dec = re.escape(profile.decimal_separator)
        if profile.thousands_separator:
            thou = re.escape(profile.thousands_separator)
            whole = "(?:[0-9]{1,3}(?:%s[0-9]{3})+|[0-9]+)" % thou
        else:
            thou = None
            whole = "[0-9]+"
        self.thousands = profile.thousands_separator
        self.decimal = profile.decimal_separator
        self.signed = re.compile("([+-]?)(%s)(?:%s([0-9]+))?" % (whole, dec))
        self.paren = re.compile(r"\((%s)(?:%s([0-9]+))?\)" % (whole, dec))
        self.currency = profile.currency

    def parse(self, cell):
        m = self.paren.fullmatch(cell)
        if m:
            sign = "-"
            whole, frac = m.group(1), m.group(2)
        else:
            m = self.signed.fullmatch(cell)
            if not m:
                raise _Bad("invalid amount '%s'" % cell)
            sign, whole, frac = m.group(1), m.group(2), m.group(3)
        if self.thousands:
            whole = whole.replace(self.thousands, "")
        text = ("-" if sign == "-" else "") + whole + ("." + frac if frac is not None else "")
        try:
            return Money(parse_amount(text, self.currency), self.currency)
        except MoneyError as exc:
            exp = CURRENCIES[self.currency].exponent
            raise _Bad(
                "invalid amount '%s': %s allows at most %d decimal places" % (cell, self.currency, exp)
            ) from exc


def _find_column(spec, header):
    if spec.startswith("#"):
        return int(spec[1:]) - 1
    want = spec.strip(" ").lower()
    for index, cell in enumerate(header):
        if cell.strip().lower() == want:
            return index
    raise CsvImportError("column '%s' not found in the header" % spec)


def _key_of(tx, account):
    for posting in tx.postings:
        if posting.account == account and posting.amount is not None:
            return (tx.date, posting.amount, tx.payee)
    return None


def import_csv(text, profile, rules=None, existing=()):
    if not isinstance(text, str):
        raise CsvImportError("csv must be given as text, got '%s'" % (text,))
    profile = _coerce_profile(profile)
    rule_set = _coerce_rules(rules)
    try:
        matcher = _compile_date_format(profile.date_format)
    except _Bad as exc:
        raise CsvImportError(str(exc)) from None
    if text.startswith("﻿"):
        text = text[1:]
    pos = _skip_lines(text, profile.skip_rows)
    records = _records(text, pos, profile.delimiter, profile.skip_rows + 1)
    records = ((ln, cells) for ln, cells in records if any(c.strip() != "" for c in cells))
    result = ImportResult()

    specs = {
        "date": profile.date_column,
        "payee": profile.payee_column,
        "narration": profile.narration_column,
        "amount": profile.amount_column,
        "debit": profile.debit_column,
        "credit": profile.credit_column,
    }
    if profile.has_header:
        first = next(records, None)
        if first is None:
            raise CsvImportError("the file has no header row")
        header = first[1]
    else:
        header = []
    index = {}
    for key, spec in specs.items():
        if spec is not None:
            index[key] = _find_column(spec, header)

    existing_count = Counter()
    for tx in existing:
        key = _key_of(tx, profile.account) if hasattr(tx, "postings") else None
        if key is not None:
            existing_count[key] += 1
    seen = Counter()
    amounts = _Amounts(profile)

    def cell(cells, key):
        i = index[key]
        if i >= len(cells):
            raise _Bad("row is too short: no value for column '%s'" % specs[key])
        return cells[i]

    for number, cells in records:
        try:
            when = _parse_cell_date(cell(cells, "date").strip(), matcher)
            payee = _clean(cell(cells, "payee"))
            if payee == "":
                raise _Bad("payee is empty")
            narration = ""
            if "narration" in index and index["narration"] < len(cells):
                narration = _clean(cells[index["narration"]])
            if "amount" in index:
                text_amount = cell(cells, "amount").strip()
                if text_amount == "":
                    raise _Bad("amount is empty")
                amount = amounts.parse(text_amount)
            else:
                debit = cell(cells, "debit").strip()
                credit = cell(cells, "credit").strip()
                if debit and credit:
                    raise _Bad("both debit ('%s') and credit ('%s') are filled" % (debit, credit))
                if not debit and not credit:
                    raise _Bad("neither debit nor credit is filled")
                amount = amounts.parse(credit) if credit else -amounts.parse(debit)
            if profile.negate:
                amount = -amount
            if amount.minor == 0:
                raise _Bad("amount is zero")
            counter = profile.default_account
            flag = profile.flag
            tags = set(profile.tags)
            if rule_set is not None:
                won = rule_set.apply(
                    {"payee": payee, "narration": narration, "date": when, "amount": amount}
                )
                if won is not None:
                    counter = won.get("account", counter)
                    payee = won.get("payee", payee)
                    narration = won.get("narration", narration)
                    flag = won.get("flag", flag)
                    tags.update(won.get("tags", ()))
            if counter is None:
                raise _Bad("no account: no rule gave one and there is no default_account")
        except _Bad as exc:
            result.errors.append((number, str(exc)))
            continue
        tx = Transaction(
            when, payee, narration,
            [Posting(profile.account, amount), Posting(counter, -amount)],
            tuple(sorted(tags)), flag, None,
        )
        key = (when, amount, payee)
        seen[key] += 1
        if seen[key] <= existing_count[key]:
            result.duplicates.append(tx)
        else:
            result.transactions.append(tx)
    return result

